  Lemma arep_after_transfer : bg + bt <= kQuarantineMaxSize -> AREP s3 m3.
  Proof.
    intros LE. apply AREP_of_AREPQ; [exact arepq_after_transfer|]. pose proof (WFQ_consts _ _ _ WQ) as (C1 & _ & C3).
